INSERT INTO `quest_template_locale` (`ID`, `locale`, `LogTitle`, `LogDescription`, `QuestDescription`) VALUES
(40390, 'ruRU', 'Священная земля', '', ''),
(40635, 'ruRU', 'Убийца Сашж''тар', 'Убейте 12 наг Сашж''тар в заливе Лазурного Шквала.', 'Не могу поверить, что Трондира больше нет.$B$BКлянусь рогами на моей голове, мы отомстим за всю боль, что Сашж''тар причинили нам!$B$BВперёд, $n. Убей их! Убей их всех!'),
(40637, 'ruRU', 'Доказательство чести', 'Вернитесь к Торил в Яндвике.', '<Брандольф тяжело дышит.>$B$BЭта пещера станет моим последним пристанищем, $n.$B$BНайди Торил. Расскажи ей о том, что случилось здесь сегодня.$B$BРасскажи всему Яндвику, что я погиб, защищая нашу деревню...'),
(40659, 'ruRU', 'Звёзды в глазах', 'Соберите 4 морские звезды со старших обитателей рва в бухте Лазурного Шквала.', 'Думаешь, эти наги — хорошая добыча, маленький кролик?$B$B<Стокальфр усмехается.>$B$BЯ бы с удовольствием сразился с одним из этих покрытых ракушками гигантов.$B$BЕсли хочешь впечатлить меня, принеси мне звёзды с их голов. Тогда, возможно, я сочту тебя настоящим $c.'),
(40749, 'ruRU', 'Знак памяти', 'Положите 4 букета лунных лилий.', 'Цветок мирно лежит в твоей руке, мягко светясь.$b$bХотя он, кажется, не растёт где-либо рядом, небольшие букеты этого цветка есть на некоторых мемориалах здесь.$b$bВозможно, если возложить цветы на оставшиеся могилы, это облегчит печаль.'),
(40763, 'ruRU', 'Непринуждённое перераспределение', 'Соберите 20 бутылок чародейского вина.', 'В последнее время происходит тревожный ряд изменений, связанных с нашим самым ценным ресурсом — чародейским вином.\n\nЯ полагаю, Талисра подробно рассказала тебе, что происходит с ночнорождённым, когда у него нет доступа к источнику силы, вроде чародейского вина.\n\nС появлением демонов пришла нормированная выдача. Многим не хватает его для поддержания себя.\n\nПринеси мне столько чародейского вина, сколько сможешь унести. Я прослежу, чтобы оно попало к нужным людям.'),
(40779, 'ruRU', 'Нам нужно ещё больше силы!', 'Найдите заряженную сферу силы.', 'Хорошие новости, $r! Я нашёл ещё одну сферу силы.$b$bПоследний раз я видел её у лагеря ночнорождённых на юго-западе. Мне пришлось уйти оттуда, прежде чем их патрули меня заметили, но для тебя это не составит труда, правда?'),
(40906, 'ruRU', 'Змеи из глубин', 'Поговорите с Торил у Яндвика.', 'Приветствую, $c.$B$BМоя деревня Яндвик оказалась в осаде группы наг под названием Сашж''тар.$B$BОбычно я не стал бы искать помощи у чужака, но мы столкнулись с врагом, которого не способны победить.$B$BВ руинах вокруг Яндвика можно найти множество могущественных эльфийских реликвий. В обмен на твою помощь ты получишь заслуженную награду.$B$BМы договорились?'),
(40920, 'ruRU', 'Награда за камнесвязывателей', '', ''),
(40925, 'ruRU', 'Кража у Клыкокамня', '', '');
